/// the call again with them in `answers`.
extension type const AnsweredPattern.fromJson(Map<String, Object?> json) implements Object {
  AnsweredPattern({required Map<String, bool> answers, required String matchedBy}) : json = {"answers": answers, "matchedBy": matchedBy};
  /// Whether it matches each string the runner has been asked about.
  Map<String, bool> get answers => (json["answers"] as Map<String, Object?>).cast<String, bool>();
  /// The pattern as the runner's language writes it, e.g. `re.compile('npm t')`.
  String get matchedBy => json["matchedBy"] as String;
}

