/// One `expect` or `expect.soft` matcher call an attempt made.
extension type const AssertionRecord.fromJson(Map<String, Object?> json) implements Object {
  AssertionRecord({num? durationMs, required String label, required bool labelled, required String matcher, String? message, required bool soft, required String status}) : json = {"durationMs": ?durationMs, "label": label, "labelled": labelled, "matcher": matcher, "message": ?message, "soft": soft, "status": status};
  /// Async matchers only (`toHaveFile`, `toSucceed`, `.resolves`, `expect.poll`).
  num? get durationMs => json["durationMs"] as num?;
  /// `expect`'s second argument, or `<matcher> <first argument>` (or the command
  /// `c.exec` ran, or the judge's question), cut at 60 characters; ` #2`, ` #3`
  /// on repeats within the attempt.
  String get label => json["label"] as String;
  /// The eval gave the label.
  bool get labelled => json["labelled"] as bool;
  /// `toHaveFile`, `not.toBe`, `resolves.toBe`, `poll.toBe`.
  String get matcher => json["matcher"] as String;
  /// Why it failed or couldn't answer, cut at 1 KB.
  String? get message => json["message"] as String?;
  bool get soft => json["soft"] as bool;
  /// `error`: the matcher couldn't answer (a subject it can't read, an event the
  /// harness doesn't report).
