/// Camera defaults for `c.capture()`. Cascades config → profile defaults → group
/// → eval, shallow-merged. `viewport` on a level replaces the whole value. `port`
/// is not an option: pass it as the first argument to `c.capture`.
extension type const CaptureOptions.fromJson(Map<String, Object?> json) implements Object {
  CaptureOptions({bool? browser, String? model, Duration? timeout, Object? viewport}) : json = {"browser": ?browser, "model": ?model, "timeout": ?timeout, "viewport": ?viewport};
  /// `false` refuses the host `chrome-headless-shell` binary. `c.capture()` then
  /// throws.
  bool? get browser => json["browser"] as bool?;
  /// Vision model for `instructions`. Cascades like `question`. Default is the
  /// analysis model when that model accepts images; never Jev.
  String? get model => json["model"] as String?;
  /// How long to poll before failing. Default `'60s'`.
  Duration? get timeout => json["timeout"];
  /// The window and saved PNG size, or `'full-page'`. Default 1280×720.
  Object? get viewport => json["viewport"];
}

/// Chromium look-ready events. `'load'` is `window` load (`Page.loadEventFired`).
/// `'idle'` is `Page.lifecycleEvent` `networkAlmostIdle`.
typedef CaptureWait = String;

