/// A canned agent for tests and dry runs, made by `fakeHarness()` in
/// `reeval/harness`.
extension type const FakeHarnessDescriptor.fromJson(Map<String, Object?> json) implements HarnessDescriptor {
  FakeHarnessDescriptor({num? delayMs, String? effort, String? failWith, Map<String, String>? files, num? flakeRate, GatewayName? gateway, String? id, bool? ignoreAbort, String? layout, num? maxConcurrent, String? reasoning, List<List<FakeScriptStep>>? script, String? servedModel, Object? startHangs, Duration? startTimeout, String? text, List<FakeHarnessDescriptorToolsItem>? tools, FakeHarnessDescriptorWithSkill? withSkill}) : json = {"delayMs": ?delayMs, "effort": ?effort, "failWith": ?failWith, "files": ?files, "flakeRate": ?flakeRate, "gateway": ?gateway, "id": ?id, "ignoreAbort": ?ignoreAbort, "kind": "fake", "layout": ?layout, "maxConcurrent": ?maxConcurrent, "reasoning": ?reasoning, "script": ?script, "servedModel": ?servedModel, "startHangs": ?startHangs, "startTimeout": ?startTimeout, "text": ?text, "tools": ?tools, "withSkill": ?withSkill};
  /// Simulated turn length, honours the abort signal.
  num? get delayMs => json["delayMs"] as num?;
  /// Requested reasoning effort, recorded as `effort` on the cell. Use
  /// `servedModel` for what the turn reports (`fake-1[effort=medium]`). Fast is
  /// not this.
  String? get effort => json["effort"] as String?;
  /// Throw before the first turn starts, to simulate an infra failure.
  String? get failWith => json["failWith"] as String?;
  /// Files the fake agent writes into the sandbox on every turn.
  Map<String, String>? get files => (json["files"] as Map<String, Object?>?)?.cast<String, String>();
  /// Chance (0–1) that an attempt writes no files and says so, for flaky pass
  /// rates.
  num? get flakeRate => json["flakeRate"] as num?;
  /// The gateway this harness's model calls go through, by name. It skips the
  /// config's `gateway` fallback: the plan refuses a gateway that isn't listed or
  /// can't serve this harness.
  GatewayName? get gateway => json["gateway"] as GatewayName?;
  /// Cell id; defaults to `fake`.
  String? get id => json["id"] as String?;
  /// Sits out `delayMs` even after an abort, like an agent that doesn't stop when
  /// it's told to.
  bool? get ignoreAbort => json["ignoreAbort"] as bool?;
  String get kind => json["kind"] as String;
  /// Behave like this agent: its image, and where it reads rules and skills
  /// (`CLAUDE.md` and `.claude/skills` for `claude-code`,
  /// `~/.gemini/config/skills` for `antigravity`, `~/.config/opencode/skills` for
  /// `opencode`, Goose's private home for `goose`, `~/.pi/agent/skills` for `pi`,
  /// `~/.agents/skills` for `codex`, fx's private home for `fx`, Grok's private
  /// home for `grok-build`). Defaults to the fake's own (`AGENTS.md`,
  /// `.agents/skills`) in Cursor's image.
  String? get layout => json["layout"] as String?;
  /// The most attempts on this harness kind at once, across the run.
  num? get maxConcurrent => json["maxConcurrent"] as num?;
  /// A reasoning block at the start of every turn.
  String? get reasoning => json["reasoning"] as String?;
  /// Real sandbox actions, one list per `c.send` (the last list repeats), run in
  /// order before `files`. `exec` runs as the agent: with the sandbox's own
  /// variables, none of the checks'.
  List<List<FakeScriptStep>>? get script => (json["script"] as List<Object?>?)?.cast<List<FakeScriptStep>>();
  /// The model the fake agent says served each turn, as a real harness reports
  /// its resolved model and variant (`composer-2.5[fast=true]`); unset, it
  /// reports none.
  String? get servedModel => json["servedModel"] as String?;
  /// The first this many session starts of an attempt never become ready, even
  /// when aborted (`true`: every one).
  Object? get startHangs => json["startHangs"];
  /// How long the harness's session may take to become ready (its bootstrap and
  /// first session) before the attempt is an infra error, after one retry;
  /// default 90s.
  Duration? get startTimeout => json["startTimeout"];
  /// The fake agent's final message on every turn; default `Done.`.
  String? get text => json["text"] as String?;
  /// Tool calls the fake agent reports on every turn, before writing files.
  List<FakeHarnessDescriptorToolsItem>? get tools => (json["tools"] as List<Object?>?)?.cast<FakeHarnessDescriptorToolsItem>();
  /// Files and message used instead when the environment gives the agent a skill.
  FakeHarnessDescriptorWithSkill? get withSkill => json["withSkill"] as FakeHarnessDescriptorWithSkill?;
}

