/// A turn as data, as a record or another language's runner carries it: `Turn`
/// without its methods.
extension type const TurnData.fromJson(Map<String, Object?> json) implements Object {
  TurnData({required Diff diff, required num durationMs, required String? model, required String prompt, required String startedAt, required TurnStatus status, required String text, required List<TranscriptEvent> transcript, required List<WebEventType> unreported, required TokenUsage? usage}) : json = {"diff": diff, "durationMs": durationMs, "model": model, "prompt": prompt, "startedAt": startedAt, "status": status, "text": text, "transcript": transcript, "unreported": unreported, "usage": usage};
  /// Workspace changes since the eval started, as of the end of this turn.
  Diff get diff => json["diff"] as Diff;
  num get durationMs => json["durationMs"] as num;
  /// The model the harness says served the turn, e.g. `composer-2.5[fast=false]`;
  /// null when it reports none. It can differ from the requested one (an alias,
  /// or parameters it filled in).
  String? get model => json["model"] as String?;
  String get prompt => json["prompt"] as String;
  String get startedAt => json["startedAt"] as String;
  TurnStatus get status => json["status"] as TurnStatus;
  /// The agent's final message for this turn.
  String get text => json["text"] as String;
  List<TranscriptEvent> get transcript => (json["transcript"] as List<Object?>).cast<TranscriptEvent>();
  /// Event types the harness couldn't report for this turn: the agent may have
  /// searched or fetched with no event in `transcript`. `toHaveSearched()` and
  /// `toHaveFetched()` refuse such a turn. Usually `[]`; a Cursor turn whose web
  /// calls the adapter couldn't recover (its SDK drops them from the stream) is
  /// `['web-search', 'web-fetch']`.
  List<WebEventType> get unreported => (json["unreported"] as List<Object?>).cast<WebEventType>();
  /// Tokens the turn used; null when the harness reports none.
  TokenUsage? get usage => json["usage"] as TokenUsage?;
}

typedef TurnStatus = String;

